ontology_addendum.graph:
@prefix co: <https://example.com/ont_cryogenics#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

co:CoolingTechnique a rdfs:Class ;
    rdfs:label "Cooling Technique" ;
    rdfs:comment "Methods used to achieve low temperatures in cryogenic experiments, such as liquid helium cooling." .

co:Cryogenics a rdfs:Class ;
    rdfs:label "Cryogenics" ;
    rdfs:comment "A field of physics that studies the behavior of materials at low temperatures, particularly near absolute zero." .

co:Material a rdfs:Class ;
    rdfs:label "Material" ;
    rdfs:comment "Substances or components used in cryogenic experiments, such as niobium and helium." .

co:QuantumFluids a rdfs:Class ;
    rdfs:label "Quantum Fluids" ;
    rdfs:comment "Fluids that exhibit quantum mechanical effects at macroscopic scales, typically at low temperatures." ;
    rdfs:subClassOf co:Cryogenics .

co:Superconductivity a rdfs:Class ;
    rdfs:label "Superconductivity" ;
    rdfs:comment "A phenomenon where a material exhibits zero electrical resistance and expulsion of magnetic fields at low temperatures." ;
    rdfs:subClassOf co:Cryogenics .

<https://example.com/ont_cryogenics> a owl:Ontology ;
    rdfs:label "Cryogenics Ontology" ;
    dcterms:description "The Cryogenics Ontology provides a structured framework for representing concepts and relationships in the field of low-temperature physics, particularly focusing on superconductivity and quantum fluids. It aims to facilitate the sharing and integration of knowledge related to cryogenic materials, experimental techniques, and fundamental properties of quantum materials at ultra-low temperatures." ;
    dcterms:title "cryogenics" ;
    rdfs:comment "The Cryogenics Ontology provides a structured framework for representing concepts and relationships in the field of low-temperature physics, particularly focusing on superconductivity and quantum fluids. It aims to facilitate the sharing and integration of knowledge related to cryogenic materials, experimental techniques, and fundamental properties of quantum materials at ultra-low temperatures." ;
    owl:versionInfo "1.0.0" .

co:hasCoolingTechnique a rdf:Property ;
    rdfs:label "has cooling technique" ;
    rdfs:comment "Links cryogenics to the cooling techniques used in experiments." ;
    rdfs:domain co:Cryogenics ;
    rdfs:range co:CoolingTechnique .

co:hasMaterial a rdf:Property ;
    rdfs:label "has material" ;
    rdfs:comment "Links a cooling technique to the material being cooled." ;
    rdfs:domain co:CoolingTechnique ;
    rdfs:range co:Material .

co:hasQuantumFluid a rdf:Property ;
    rdfs:label "has quantum fluid" ;
    rdfs:comment "Indicates that a material behaves as a quantum fluid under specific conditions." ;
    rdfs:domain co:Material ;
    rdfs:range co:QuantumFluids .

co:hasSuperconductivity a rdf:Property ;
    rdfs:label "has superconductivity" ;
    rdfs:comment "Indicates that a material exhibits superconductivity at certain temperatures." ;
    rdfs:domain co:Material ;
    rdfs:range co:Superconductivity .
